CREATE TABLE IF NOT EXISTS `recipes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL,
  `meal` varchar(100) DEFAULT NULL,
  `time` varchar(100) DEFAULT NULL,
  `difficulty` varchar(100) DEFAULT NULL,
  `description` text,
  `ingredients` text,
  `steps` text,
  `suitable_for` text,
  `youtube_query` varchar(255) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

TRUNCATE TABLE `recipes`;
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (1, 'Cháo yến mạch cá hồi', 'Bữa sáng', '20 phút', 'Dễ', 'Mềm, dễ ăn và giàu đạm; nêm nhạt, không dùng nước dùng đóng gói.', '[\"yến mạch\",\"cá hồi\",\"gừng\",\"rau xanh\"]', '[\"Rửa sạch cá và hấp với vài lát gừng.\",\"Nấu yến mạch với nước đến khi mềm.\",\"Gỡ cá, cho vào cháo và nêm nhạt.\"]', '[\"tieu-duong\",\"tang-huyet-ap\",\"mo-mau\"]', 'cháo yến mạch cá hồi nêm nhạt', 'assets/images/recipe-chao-yen-mach-ca-hoi.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (2, 'Trứng hấp rau củ', 'Bữa sáng', '15 phút', 'Rất dễ', 'Món mềm, dễ nhai, có thể dùng cùng một phần nhỏ tinh bột.', '[\"trứng\",\"cà rốt\",\"nấm\",\"rau xanh\"]', '[\"Đánh trứng với nước ấm.\",\"Thêm rau củ cắt nhỏ.\",\"Hấp lửa vừa đến khi trứng vừa chín.\"]', '[\"tieu-duong\",\"tang-huyet-ap\",\"mo-mau\"]', 'trứng hấp rau củ mềm dễ ăn', 'assets/images/recipe-trung-hap-rau-cu.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (3, 'Cá hấp gừng', 'Bữa trưa', '30 phút', 'Dễ', 'Nhiều đạm, dễ ăn; có thể điều chỉnh gia vị theo hướng dẫn bác sĩ.', '[\"cá tươi\",\"gừng\",\"hành lá\",\"chanh\"]', '[\"Làm sạch cá, khứa nhẹ hai mặt.\",\"Xếp gừng lên cá và hấp chín.\",\"Dùng chanh, hành và rau thơm thay cho nhiều muối.\"]', '[\"tieu-duong\",\"tang-huyet-ap\",\"mo-mau\",\"gan-nhiem-mo\"]', 'cá hấp gừng ít muối cách làm', 'assets/images/recipe-ca-hap-gung.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (4, 'Cá hấp rau thơm', 'Bữa trưa', '25 phút', 'Dễ', 'Thanh đạm, ít muối, giàu axit béo omega-3 hỗ trợ tim mạch.', '[\"cá phi lê\",\"thì là\",\"hành hoa\",\"tiêu nhạt\"]', '[\"Làm sạch cá và ướp tiêu nhẹ.\",\"Lót thì là, hành hoa dưới đáy đĩa hấp.\",\"Hấp cách thủy 15 phút đến khi chín mềm.\"]', '[\"tim-mach\",\"tang-huyet-ap\",\"than-man\"]', 'cá hấp rau thơm thanh đạm', 'assets/images/recipe-ca-hap-rau-thom.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (5, 'Canh rau củ thịt nạc', 'Bữa trưa', '30 phút', 'Dễ', 'Nhiều rau, ít mỡ; phù hợp bữa gia đình khi nêm vừa phải.', '[\"bí đỏ\",\"cà rốt\",\"thịt nạc\",\"hành\"]', '[\"Sơ chế rau củ và thịt nạc.\",\"Nấu thịt chín rồi thêm rau củ.\",\"Nêm nhạt, dùng khi còn ấm.\"]', '[\"tieu-duong\",\"tang-huyet-ap\",\"mo-mau\",\"da-day\"]', 'canh rau củ thịt nạc ít muối', 'assets/images/recipe-canh-rau-cu-thit-nac.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (6, 'Đậu phụ sốt nấm nhạt', 'Bữa trưa', '15 phút', 'Rất dễ', 'Món đạm thực vật nhẹ bụng, phù hợp khi cần giảm món chiên.', '[\"đậu phụ\",\"nấm\",\"gừng\",\"hành lá\"]', '[\"Áp chảo đậu phụ với ít dầu hoặc hấp.\",\"Xào nấm với gừng.\",\"Cho đậu vào, thêm chút nước và nêm nhạt.\"]', '[\"tieu-duong\",\"tang-huyet-ap\",\"mo-mau\",\"gout\"]', 'đậu phụ sốt nấm nhạt dễ làm', 'assets/images/recipe-dau-phu-sot-nam.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (7, 'Đậu phụ hấp rau củ', 'Bữa tối', '20 phút', 'Rất dễ', 'Thanh mát, giàu xơ và đạm thực vật dễ tiêu hóa.', '[\"đậu phụ non\",\"đậu Hà Lan\",\"ngô ngọt\",\"cà rốt\"]', '[\"Cắt đậu hũ thành khối vừa ăn.\",\"Rải rau củ xung quanh đĩa.\",\"Hấp chín 10 phút, dùng cùng nước tương nhạt.\"]', '[\"gan-nhiem-mo\",\"beo-phi\",\"tang-huyet-ap\"]', 'đậu phụ hấp rau củ thanh nhiệt', 'assets/images/recipe-dau-phu-hap-rau-cu.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (8, 'Rau xanh và dưa chuột', 'Bữa tối', '10 phút', 'Rất dễ', 'Món rau tươi nhẹ nhàng, dùng cùng gia vị tự nhiên và ít muối.', '[\"rau xanh\",\"dưa chuột\",\"chanh\",\"dầu ô liu\"]', '[\"Rửa sạch rau và dưa chuột.\",\"Cắt vừa ăn, để ráo nước.\",\"Trộn với chanh và một ít dầu ô liu.\"]', '[\"tieu-duong\",\"tang-huyet-ap\",\"mo-mau\",\"tao-bon\",\"beo-phi\"]', 'salad rau xanh dưa chuột sốt chanh', 'assets/images/recipe-rau-xanh-dua-chuot.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (9, 'Rau củ hấp phần nhỏ', 'Bữa tối', '15 phút', 'Rất dễ', 'Bổ sung chất xơ hòa tan giúp kiểm soát đường huyết và huyết áp.', '[\"súp lơ\",\"cà rốt\",\"đậu bắp\",\"su hào\"]', '[\"Rửa sạch và cắt miếng vừa ăn.\",\"Hấp cách thủy khoảng 8-10 phút.\",\"Dùng nóng để giữ nguyên vitamin tự nhiên.\"]', '[\"tieu-duong\",\"than-man\",\"mo-mau\"]', 'rau củ luộc hấp chấm kho quẹt ít mặn', 'assets/images/recipe-rau-cu-hap-phan-nho.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (10, 'Thịt nạc cuộn rau xanh', 'Bữa tối', '25 phút', 'Dễ', 'Đầy đủ dinh dưỡng đạm - xơ mà không chứa dầu mỡ dư thừa.', '[\"thịt nạc thăn\",\"xà lách\",\"rau thơm\",\"dưa leo\"]', '[\"Luộc chín thịt nạc với chút gừng.\",\"Thái lát mỏng.\",\"Cuộn cùng rau sống tươi sạch.\"]', '[\"tieu-duong\",\"thieu-mau\",\"beo-phi\"]', 'thịt nạc luộc cuốn rau sống ngon', 'assets/images/recipe-thit-nac-cuon-rau-xanh.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (11, 'Khoai lang nướng mềm', 'Bữa phụ', '35 phút', 'Dễ', 'Bữa phụ đơn giản; vẫn cần tính vào tổng lượng tinh bột trong ngày.', '[\"khoai lang\"]', '[\"Rửa sạch và chọc vài lỗ trên vỏ.\",\"Nướng đến khi mềm.\",\"Ăn khẩu phần vừa phải, không thêm đường.\"]', '[\"tieu-duong\",\"tao-bon\",\"beo-phi\"]', 'khoai lang nướng mềm không dầu', 'assets/images/recipe-khoai-lang-nuong-mem.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (12, 'Sữa chua trái cây không đường', 'Bữa phụ', '5 phút', 'Rất dễ', 'Bữa phụ nhanh; kiểm tra dị ứng sữa và không thêm siro đường.', '[\"sữa chua không đường\",\"táo\",\"dâu\",\"hạt không muối\"]', '[\"Rửa sạch và cắt trái cây.\",\"Cho sữa chua vào bát.\",\"Thêm lượng nhỏ trái cây và hạt.\"]', '[\"tieu-duong\",\"mo-mau\",\"tao-bon\"]', 'sữa chua trái cây không đường bữa phụ', 'assets/images/recipe-sua-chua-trai-cay.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (13, 'Cháo bí đỏ thịt nạc', 'Bữa tối', '30 phút', 'Dễ', 'Món mềm, ấm, dễ ăn; nên điều chỉnh khẩu phần theo nhu cầu cá nhân.', '[\"bí đỏ\",\"gạo\",\"thịt nạc\",\"gừng\"]', '[\"Nấu gạo và bí đỏ đến mềm.\",\"Thêm thịt nạc băm đã hấp chín.\",\"Nêm nhạt và dùng ấm.\"]', '[\"da-day\",\"trao-nguoc\",\"loang-xuong\"]', 'cháo bí đỏ thịt nạc mềm dễ ăn', 'assets/images/recipe-chao-bi-do-thit-nac.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (14, 'Yến mạch cá hồi rau xanh', 'Bữa sáng', '25 phút', 'Dễ', 'Bữa sáng hoàn hảo giàu canxi, sắt và omega-3 cho cả gia đình.', '[\"yến mạch cán dẹt\",\"cá hồi tươi\",\"rau cải bó xôi\",\"dầu mè\"]', '[\"Nấu yến mạch với nước dùng thanh.\",\"Cho cá hồi xé nhỏ và rau thái sợi vào.\",\"Khuấy đều 3 phút và tắt bếp.\"]', '[\"tim-mach\",\"loang-xuong\",\"thieu-mau\"]', 'yến mạch nấu cá hồi rau chân vịt', 'assets/images/recipe-yen-mach-ca-hoi-rau-xanh.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (15, 'Cá hấp rau thơm không muối', 'Bữa trưa', '25 phút', 'Dễ', 'Món hấp ít dầu; vẫn cần kiểm soát khẩu phần và lượng muối theo tình trạng tim, gan của từng người.', '[\"cá trắng\",\"gừng\",\"hành lá\",\"rau thơm\",\"chanh\"]', '[\"Làm sạch cá và đặt lên xửng hấp.\",\"Thêm gừng, hành lá, rau thơm rồi hấp chín.\",\"Dùng chanh và rau thơm thay cho nước chấm mặn.\"]', '[\"tim-mach\",\"gan-nhiem-mo\"]', 'cá hấp rau thơm không muối tốt cho tim mạch', 'assets/images/recipe-ca-hap-rau-thom.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (16, 'Đậu phụ hấp rau củ', 'Bữa trưa', '20 phút', 'Rất dễ', 'Món nhẹ, không dùng nội tạng hay nước dùng cô đặc; người bệnh gút cần trao đổi bác sĩ về khẩu phần đạm và lượng nước.', '[\"đậu phụ\",\"bắp cải\",\"cà rốt\",\"gừng\",\"chanh\"]', '[\"Cắt đậu phụ và rau củ thành miếng vừa ăn.\",\"Hấp rau củ gần chín rồi thêm đậu phụ.\",\"Dùng chanh, gừng và lượng muối nhỏ theo hướng dẫn.\"]', '[\"gout\"]', 'đậu phụ hấp rau củ nhạt cho người bệnh gút', 'assets/images/recipe-dau-phu-hap-rau-cu.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (17, 'Yến mạch cá hồi rau xanh', 'Bữa sáng', '20 phút', 'Dễ', 'Ưu tiên cách nấu đơn giản và không đường; tổng năng lượng vẫn cần được cá nhân hóa.', '[\"yến mạch\",\"cá hồi\",\"rau xanh\",\"gừng\"]', '[\"Hấp cá hồi với gừng rồi gỡ nhỏ.\",\"Nấu yến mạch với nước đến khi mềm.\",\"Thêm cá và rau xanh, không thêm đường hoặc nước dùng nhiều muối.\"]', '[\"gan-nhiem-mo\"]', 'yến mạch cá hồi rau xanh không đường', 'assets/images/recipe-yen-mach-ca-hoi-rau-xanh.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (18, 'Thịt nạc cuộn rau xanh', 'Bữa trưa', '25 phút', 'Dễ', 'Có thể bổ sung đạm và sắt từ thực phẩm; thiếu máu vẫn cần tìm nguyên nhân và dùng thuốc theo chỉ định.', '[\"thịt nạc\",\"rau cải\",\"cà rốt\",\"chanh\"]', '[\"Trải rau cải, đặt một lượng nhỏ thịt nạc vào giữa.\",\"Cuộn lại và hấp chín kỹ.\",\"Dùng cùng rau củ và thực phẩm giàu vitamin C theo khẩu phần phù hợp.\"]', '[\"thieu-mau\"]', 'thịt nạc cuộn rau xanh hấp mềm', 'assets/images/recipe-thit-nac-cuon-rau-xanh.png');
INSERT INTO `recipes` (`id`, `title`, `meal`, `time`, `difficulty`, `description`, `ingredients`, `steps`, `suitable_for`, `youtube_query`, `image`) VALUES (19, 'Rau củ hấp phần nhỏ', 'Bữa trưa', '20 phút', 'Rất dễ', 'Đây chỉ là nền món ít muối; loại rau, khẩu phần, kali, phốt pho, đạm và lượng nước phải theo giai đoạn bệnh và xét nghiệm.', '[\"bắp cải\",\"súp lơ\",\"cà rốt\",\"chanh\"]', '[\"Rửa và cắt rau củ thành miếng vừa ăn.\",\"Hấp chín mềm, không dùng nước hầm cô đặc.\",\"Chỉ thêm gia vị theo lượng muối, kali và nước được bác sĩ cho phép.\"]', '[\"than-man\"]', 'rau củ hấp nêm nhạt cho bệnh thận', 'assets/images/recipe-rau-cu-hap-phan-nho.png');

CREATE TABLE IF NOT EXISTS `medical_contacts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `type` varchar(255) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `address` text,
  `working_hours` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

TRUNCATE TABLE `medical_contacts`;
